#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

int sumaCyfr(int n) {
    int s = 0;
    while (n > 0) { s += n % 10; n /= 10; }
    return s;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    vector<int> armstrong;
    cout << "a) Sprawdzenie Armstronga:" << endl;
    while (plik >> n) {
        string s = to_string(n);
        int k = s.length();
        long long suma = 0;
        for (char c : s) {
            int d = c - '0';
            long long p = 1;
            for (int i = 0; i < k; i++) p *= d;
            suma += p;
        }
        cout << n << " (" << k;
        if (k >= 5) cout << " cyfr): ";
        else cout << " cyfry): ";
        for (int i = 0; i < k; i++) {
            if (i > 0) cout << " + ";
            cout << s[i] << "^" << k;
        }
        cout << " = " << suma << " -> " << (suma == n ? "TAK" : "NIE") << endl;
        if (suma == n) armstrong.push_back(n);
    }
    cout << endl << "b) Armstrong z najwieksza suma cyfr: ";
    int maxSuma = -1, maxN = -1;
    for (int a : armstrong) {
        int sc = sumaCyfr(a);
        if (sc > maxSuma) { maxSuma = sc; maxN = a; }
    }
    cout << maxN << ", suma cyfr = " << maxSuma << endl;
    cout << "Liczb Armstronga: " << armstrong.size() << endl;
    return 0;
}
```

**Wyjasnienie**: Wieloetapowe: (1) konwersja na string dla policzenia cyfr, (2) potegowanie kazdej cyfry, (3) porownanie sumy z oryginalem. Dodatkowe wyzwanie: znalezienie Armstronga z max suma cyfr.

